"use client";
/* Fetch, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Fetch(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("fetch"); }, []);
  return React.createElement("piix-pal", { "pal": "fetch", ...piixAttrs(props) });
}

export default Fetch;
